P = [
 dict(pmid='43057362', doi='10.1016/j.envres.2026.126250', journal='Environ Res', title='Association of early-life particulate matter exposure with childhood carotid intima-media thickness: identification of sensitive windows and exploratory analysis of vitamin D status.', tier='B', basis='Not stated', short='Wuhan 990 children: early-life PM2.5/PM10 with thicker carotid IMT (ICA 8.49%); sensitive windows in the first postnatal year', design='Cross-sectional study', pm='Pregnancy and first-postnatal-year PM2.5 and PM10 at weekly resolution (estimation method and increment not in abstract)', geo='China (Wuhan)', endpoint='Childhood carotid intima-media thickness (common and internal carotid)', affil='Hubei Key Laboratory of Occupational Hazard Identification and Control, Wuhan, China; Wuhan Asia General Hospital, China', n='990 children aged 2-14 enrolled in Wuhan, December 2023-July 2024; pregnancy and first-postnatal-year PM2.5 and PM10; generalized linear models and weekly distributed-lag non-linear models. Early-life PM was associated with thicker cIMT, percent changes from 2.67% (95% CI 0.35-5.04) to 9.98% (4.37-15.89); internal carotid exceeded common carotid (PM2.5 8.49%, 3.09-14.17 vs 2.87%, 0.71-5.09). Sensitive windows were postnatal weeks 11-17 and 48-52 for CCA and 6-22 for ICA. No PM x vitamin D interaction was significant. Weakness: one cIMT measurement years after exposure, wide age range, residential history reconstructed retrospectively, and exposure model and increment not stated in the abstract. Relevance: week-resolved infant windows are where home-level sensing would outperform annual surfaces.', sub=corpus.CVM),
 dict(pmid='43052903', doi='10.1186/s12889-026-29162-7', journal='BMC Public Health', title='Long-term exposure to particulate matter and the risk of stroke in Chinese adults: findings from the China Health and Retirement Longitudinal Study (CHARLS).', tier='B', basis='Satellite-fused', short='CHARLS 7203 adults 45+: PM10 HR 1.144 per 10 ug/m3 for stroke; ammonium, BC and sulfate drive the PM2.5 component mixture', design='Prospective cohort', pm='Annual PM10, PM2.5 and PM2.5 components from satellite-based machine-learning estimates', geo='China (nationwide)', endpoint='Incident stroke', affil="First Affiliated Hospital of Xi'an Jiaotong University, China; First Affiliated Hospital of Xi'an Jiaotong University, China", n='7,203 CHARLS participants aged 45+, 2011-2018, mean follow-up 7.88 years (56,734 person-years), 5.1% incident stroke; annual PM10, PM2.5 and PM2.5 components from satellite-based machine-learning estimates; Cox models, restricted cubic splines and quantile g-computation. PM10 was linearly associated with stroke (HR 1.144 per 10 ug/m3, 95% CI 1.101-1.188); PM2.5 and its components were non-linear. A simultaneous one-quantile increase in all components gave a 1.439-fold risk, with ammonium, black carbon and sulfate the main contributors. Weakness: stroke is self-reported physician diagnosis, the spatial resolution of exposure assignment is not stated, the PM10 HR is large relative to the literature, and the joint-effect CI is not in the abstract. Relevance: BC and sulfate as drivers again point to component-resolving measurement beyond optical mass.', sub=corpus.CVM),
 dict(pmid='43054216', doi='10.3389/fpubh.2026.2000035', journal='Front Public Health', title='Population-weighted and area-weighted ambient PM(2.5) and O(3) concentrations in China from 2015 to 2024.', tier='B', basis='Satellite-fused', short='China 2015-2024: population-weighted PM2.5 53.1 to 31.3 ug/m3 (-2.51/yr), 6-10 ug/m3 above area-weighted; O3 rising', design='Cross-sectional population-weighted exposure', pm='CHAP v4 annual PM2.5 and v3 MDA8 O3 rasters linked to WorldPop population counts', geo='China (nationwide)', endpoint='Population- vs area-weighted annual PM2.5 and O3, national and 0.2-degree trends', affil="Affiliated Panyu Central Hospital of Guangzhou Medical University, China; Second People's Hospital of Panyu District, China", n="Annual ChinaHighAirPollutants PM2.5 (v4) and MDA8 O3 (v3) rasters linked to WorldPop population counts, 2015-2024. Population-weighted PM2.5 fell from 53.06 to 31.25 ug/m3 (slope -2.51 ug/m3 per year, 95% CI -3.16 to -1.87) and area-weighted from 42.69 to 24.83; population-weighted O3 rose from 77.06 to 96.75 ug/m3 (+1.99 per year, 1.19-2.79). Population weighting added about 6-10 ug/m3 to national PM2.5; spatial slopes were stable at 0.1-0.25 degree aggregation. Weakness: descriptive only, and the CHAP product's own error, larger where monitors are sparse, is not propagated into the trends. Relevance: the persistent population-versus-area gap is the argument for siting networks by population rather than by area.", sub=corpus.EXPO),
 dict(pmid='43055984', doi='10.1007/s10661-026-16179-z', journal='Environ Monit Assess', title='Long-term PM(2.5) trends and spatial heterogeneity over Delhi-NCR: insights from detrending and meteorological normalization.', tier='B', basis='Reference / regulatory monitor', short='Delhi-NCR 38 sites 2017-2024: deweathered PM2.5 down 18.75% since 2018; secondary 46.6%; short-term variance 68-70%', design='Statistical analysis of monitoring data', pm='PM2.5 and PM10 at 38 regulatory sites; ERA5 ventilation-coefficient normalisation, KZ decomposition, primary/secondary fractionation', geo='India (Delhi)', endpoint='Meteorologically normalised PM trends and spatial hotspots', affil='Indian Institute of Technology Bombay, India; Indian Institute of Technology Bombay, India', n='PM2.5 and PM10 at 38 Delhi-NCR monitoring sites (traffic, residential, industrial, commercial), 2017-2024, normalised with an ERA5 ventilation coefficient and decomposed with Kolmogorov-Zurbenko filtering, with primary/secondary fractionation and geospatial analysis. Winter and post-monsoon PM2.5 averaged 168 and 161 ug/m3 vs 43 in the monsoon. The annual ventilation coefficient rose 35%; deweathered PM2.5 fell 18.75% from 2018 to 2024, with both primary and secondary fractions declining; secondary PM2.5 was 46.6% overall. Short-term variability carried 68-70% of variance; post-COVID reductions of 10-30% were widespread but hotspots persisted. Weakness: no uncertainty on the trend, fractionation method not described in the abstract, uneven site completeness. Relevance: with short-term variance dominant, network density and temporal resolution set exposure accuracy in Delhi.', sub=corpus.EXPO),
]
